namespace CheckoutPricing.Domain;

public sealed class LoyaltyDiscountPolicy
{
    private const int MinimumSubtotalCents = 3_000;
    private const int CapCents = 2_000;

    public int DiscountCentsFor(int subtotalCents, LoyaltyTier loyaltyTier) =>
        subtotalCents < MinimumSubtotalCents
            ? 0
            : Math.Min(subtotalCents * PercentFor(loyaltyTier) / 100, CapCents);

    private static int PercentFor(LoyaltyTier loyaltyTier) => loyaltyTier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        LoyaltyTier.Platinum => 20,
        _ => throw new ArgumentOutOfRangeException(nameof(loyaltyTier))
    };
}

