namespace CheckoutPricing.Domain;

public sealed class ShippingPolicy
{
    private const int StandardFeeCents = 490;
    private const int ExpressFeeCents = 990;
    private const int FreeStandardFromCents = 5_000;

    public int FeeCentsFor(int payableTotalCents, LoyaltyTier loyaltyTier, bool express) =>
        express ? ExpressFeeCents.IfNotFor(loyaltyTier == LoyaltyTier.Platinum) : StandardFeeCents.IfNotFor(StandardIsFree(payableTotalCents, loyaltyTier));

    private static bool StandardIsFree(int payableTotalCents, LoyaltyTier loyaltyTier) =>
        payableTotalCents >= FreeStandardFromCents || loyaltyTier is LoyaltyTier.Gold or LoyaltyTier.Platinum;
}

internal static class FeeExtensions
{
    public static int IfNotFor(this int feeCents, bool free) => free ? 0 : feeCents;
}

